export interface LectureData {
  id: string;
  title: string;
  transcript: string;
}

// Full-mock lectures double as practice items; new mock questions appear here automatically.
const fromMock = (n: number, items: { id: string; title: string; transcript: string }[]): LectureData[] =>
  items.map(i => ({ id: `${i.id}-rl`, title: `${i.title.replace(/^.*?\(/, '').replace(/\)$/, '')} (Mock ${n})`, transcript: i.transcript }));

